inline constexpr std::uint8_t kNoCond = 255;
inline constexpr std::uint16_t kNoProgram = 65535;
inline constexpr std::uint8_t kNoFeature = 255;

/* What the table records about a form. */
struct FormInfo final {
	const char *name;
	const char *mnemonic;
	/* A word LLVM MC decodes to this encoding (zero for the pseudo-forms). */
	std::uint32_t witness;
	/* Bits the encoding requires to be 0 or 1 (SBZ and SBO); a word that
	 * differs is UNPREDICTABLE. */
	std::uint32_t should_mask;
	std::uint32_t should_value;
	std::uint16_t program;
	std::uint16_t traits;
	Isa isa;
	/* The part of the profile the form belongs to. */
	Level level;
	Availability availability;
	Check check;
	/* The Feature the form needs, or kNoFeature. */
	std::uint8_t feature;
	/* Bit position of the form's own condition field, or kNoCond. */
	std::uint8_t cond_low;
	/* The form executes only when its condition passes. */
	bool conditional;
	/* The form is decoded but executes as a NOP at EL0 (CPS). */
	bool nop;
	/* A32 data processing with S set and Rd 15 is an exception return,
	 * UNPREDICTABLE at EL0. */
	bool alu_exception_return;
};

/* A field-pattern predicate on up to three joined fields: the value of
 * the fields, most significant first, masked by keep, equals want (or
 * does not, when negate). */
struct Constraint final {
	std::uint8_t low[3];
	std::uint8_t width[3];
	bool negate;
	std::uint16_t keep;
	std::uint16_t want;
};

enum class RowKind : std::uint8_t {
	instruction,
	/* The index marks the partition UNPREDICTABLE. */
	unpredictable,
	reserved_hint,
};

/* One partition of the encoding space the index allocates. */
struct Row final {
	std::uint32_t mask;
	std::uint32_t value;
	std::uint16_t form;
	RowKind kind;
	std::uint8_t constraint_count;
	std::uint16_t constraint_first;
};

/* A node of the per-instruction-set decision trees. An inner node tests
 * the bit and continues at its zero or one child; a leaf holds a count
 * of candidate rows, tried in order, at an offset in kLeafRows. A subtree
 * that occurs more than once is stored once, and a child precedes its
 * parent. */
struct Node final {
	std::int16_t bit;
	std::uint16_t first;
	std::uint16_t second;
};

inline constexpr std::size_t kNodeCount = 4584;
inline constexpr std::size_t kLeafRowCount = 6813;
inline constexpr std::size_t kConstraintCount = 239;

extern const FormInfo kForms[kFormCount];
extern const Row kRows[kRowCount];
extern const Constraint kConstraints[kConstraintCount];
extern const Node kNodes[kNodeCount];
extern const std::uint16_t kLeafRows[kLeafRowCount];
/* Roots of the A32, T16 and T32 trees in kNodes. */
extern const std::uint16_t kTreeRoots[3];

/* Run the operand program of a form on a word. */
Outcome run_program(std::uint16_t program, std::uint32_t word,
	const Context &ctx, Operands &out) noexcept;

